import {initializeLearningChecks,switchLearningExperiment,afterScientificObservation,afterMentorResponse,exportLearningEvidence,resetLearningEvidence} from './check-ui.js';
const $=id=>document.getElementById(id);
const pickers=[...document.querySelectorAll('[data-exp]')];
const state={experiment:'sensitivity',runId:null,result:null,prediction:null,mentor:null,answer:null,selection:null,modelActive:false,modelLabel:'',pendingPlan:null,records:readRecords()};
function refreshAIChoice(){
 const mentor=state.modelActive;
 $('mentor-request-mode').textContent=mentor?
  ($('shareApproved').checked?'本次使用 '+state.modelLabel+' 生成 AI 导师反馈；提交后会取消本次授权。':'本次未授权 AI 调用：点击分析将使用本地学习指导，不会发送学习数据。'):
  '当前科学实验可以正常运行；导师反馈使用本地学习指导。';
 $('mentor-request-mode').dataset.mode=mentor&&$('shareApproved').checked?'ai':'local';
 $('plan-request-mode').textContent=mentor?
  ($('plan-model-consent').checked?'本次使用 '+state.modelLabel+' 选择经验证的实验方案；执行前仍需你批准。':'本次未授权 AI 规划：将使用本地单变量方案，不向模型发送数据。'):
  '可使用本地科学对照方案，预测和批准后才会执行实验。';
 $('plan-request-mode').dataset.mode=mentor&&$('plan-model-consent').checked?'ai':'local';
}
$('shareApproved').addEventListener('change',refreshAIChoice);
$('plan-model-consent').addEventListener('change',refreshAIChoice);
function setLens(id,message,mode='ready'){
 const card=$(id);if(!card)return;
 card.dataset.state=mode;
 card.querySelector('p').textContent=String(message||'').slice(0,190);
}
function updateResultLens(data){
 setLens('lens-hypothesis','已锁定 · '+String(state.prediction||'').slice(0,130));
 if(data.experiment==='evo-pair'){
  setLens('lens-evidence','EvoWorld 已计算 '+(data.results?.length||0)+' 条配对世界记录；样本很少，不可推断普遍因果。');
 }else{
  const m=data.metrics?.find(x=>String(x.label).includes('首次'));
  const detail=m?'首次分离观测：'+String(m.value)+' '+String(m.unit||'步'):'曲线及数值指标已由科学引擎返回';
  setLens('lens-evidence',data.engine+' · '+detail);
 }
 setLens('lens-next','先解释这些观测，再由导师提出可审核的对照实验。','attention');
}
function readRecords(){try{return JSON.parse(localStorage.getItem('ai-academy-learning-v01')||'[]')}catch{return []}}
function saveRecords(){try{localStorage.setItem('ai-academy-learning-v01',JSON.stringify(state.records.slice(-20)))}catch{}}
function clearLater(){
 for(const name of ['results','tutoring','transfer','agent-planning','plan-preview','experiment-comparison'])$(name).classList.add('hidden');
 $('mentor-output').classList.add('hidden');$('retry').classList.add('hidden');
 $('quiz-feedback').classList.add('hidden');
 state.runId=null;state.result=null;state.prediction=null;state.mentor=null;state.answer=null;state.selection=null;state.pendingPlan=null;
 document.dispatchEvent(new Event('academy:plan-reset'));
 $('shareApproved').checked=false;
 $('plan-model-consent').checked=false;
 refreshAIChoice();
 setLens('lens-hypothesis','等待你先作出科学预测','idle');
 setLens('lens-evidence','尚未运行；模型不会捏造数据','idle');
 setLens('lens-next','先依据真实证据提出问题','idle');
 document.querySelectorAll('[data-step]').forEach((x,i)=>x.classList.toggle('active',i===0));
}
function selectExperiment(exp){
 clearLater();state.experiment=exp;
 switchLearningExperiment(exp);
 $('prediction-input').disabled=false;
 ['r','x0','delta','steps','seed'].forEach(k=>$(k).disabled=false);
 pickers.forEach(x=>x.classList.toggle('selected',x.dataset.exp===exp));
 const topics={
  sensitivity:['微小的初值变化，会改变长期结果吗？','保持映射方程与参数不变，只给初始条件一个极小扰动。两条轨道会始终相近吗？'],
  logistic:['相同的非线性规律，为什么会出现不同轨道？','使用 Logistic 映射 x(n+1)=r×x(n)×(1−x(n))。在正式看到曲线前，你认为迭代会怎样变化？'],
  'evo-pair':['生命合作会提高种群数量吗？','比较同一随机种子下合作开启与关闭的两个世界。别忘了：少量重复不足以证明普遍规律。']
 };
 $('question-title').textContent=topics[exp][0];$('question-description').textContent=topics[exp][1];
 $('params').hidden=exp==='evo-pair';
 $('evo-params').hidden=exp!=='evo-pair';
 $('delta-wrap').hidden=exp!=='sensitivity';
 $('prediction-input').value='';
 $('run').disabled=true;
 $('hint').textContent='先留下事前预测，才能看到实验数据。';
 $('prediction-input').focus();
}
pickers.forEach(b=>b.addEventListener('click',()=>selectExperiment(b.dataset.exp)));
for(const id of ['r','x0','delta','steps']){
 $(id).addEventListener('input',()=>{
  const v=Number($(id).value);
  $(id+'-label').textContent=id==='r'?v.toFixed(2):id==='x0'?v.toFixed(3):id==='delta'?String(v).replace('-','−'):String(v);
 });
}
$('prediction-input').addEventListener('input',()=>{
 $('run').disabled=!$('prediction-input').value.trim();
});
async function request(path,body){
 const controller=new AbortController();
 const timeout=setTimeout(()=>controller.abort(),35000);
 try{
  const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',signal:controller.signal,body:JSON.stringify(body)});
  const data=await response.json();
  if(!response.ok)throw new Error(data.error||'请求失败（HTTP '+response.status+'）');
  return data;
 }catch(error){
  if(controller.signal.aborted)throw new Error('请求等待超过35秒，已停止等待。请查看网络或连接配置后重试；不要连续重复点击。');
  throw error;
 }finally{clearTimeout(timeout)}
}
function snapshotParams(){
 if(state.experiment==='evo-pair')return {seed:Number($('seed').value)};
 const p={r:Number($('r').value),x0:Number($('x0').value),steps:Number($('steps').value)};
 if(state.experiment==='sensitivity')p.logDelta=Number($('delta').value);
 return {params:p};
}
function activeStep(n){
 document.querySelectorAll('[data-step]').forEach(el=>el.classList.toggle('active',Number(el.dataset.step)===n));
}
function markResult(){
 const record={id:state.runId,createdAt:new Date().toISOString(),
  experiment:state.experiment,prediction:state.prediction,result:state.result,lineage:state.result?.lineage||null,mentor:null,
  transfer:null,step:'observed'};
 state.records.push(record);state.records=state.records.slice(-20);saveRecords();
 afterScientificObservation(state.result,state.prediction);
}
function setStage(what){
 $('run').disabled=what;
 $('run').textContent=what?'正在调用科学计算引擎…':'运行科学实验 →';
}
$('run').addEventListener('click',async()=>{
 const prediction=$('prediction-input').value.trim();
 if(!prediction)return;
 setStage(true);
 try{
  const experiment=state.experiment;
  const data=await request('/api/run',{experiment,prediction,...snapshotParams()});
  state.prediction=prediction;state.runId=data.runId;state.result=data;
  $('prediction-input').disabled=true;
  ['r','x0','delta','steps','seed'].forEach(k=>$(k).disabled=true);
  renderResult(data);
  $('results').classList.remove('hidden');$('tutoring').classList.remove('hidden');
  activeStep(2);markResult();
  $('results').scrollIntoView({behavior:'smooth',block:'start'});
  $('hint').textContent='已锁定本轮事前预测；点击“下一轮实验”才可更新参数。';
 }catch(e){$('hint').textContent=e.message}
 finally{setStage(false);if(state.runId)$('run').disabled=true}
});
function addMetric(root,k,v,unit=''){
 const card=document.createElement('div');card.className='metric';
 const label=document.createElement('span');label.textContent=k;
 const number=document.createElement('strong');
 number.textContent=typeof v==='number'?(Math.abs(v)<0.00001&&v!==0?v.toExponential(3):Number(v.toPrecision(6)).toString()):String(v);
 const detail=document.createElement('span');detail.textContent=unit;
 card.append(label,number,detail);root.append(card);
}
function renderResult(data){
 updateResultLens(data);
 $('source-label').textContent=data.engine+' / '+data.engineVersion;
 const plots=$('plots');plots.replaceChildren();
 $('point-selection').textContent='点击真实曲线上的某个点，选出其对应的科学数据并向导师提问。';
 $('point-selection').hidden=data.experiment==='evo-pair';
 const metrics=$('metrics');metrics.replaceChildren();
 const warn=$('warnings');warn.replaceChildren();
 if(data.experiment==='evo-pair'){
  data.results.forEach(x=>addMetric(metrics,x.condition+' · 种子'+x.seed,x.meanPopulation,'平均种群'));
  const t=document.createElement('div');t.className='plot-card';
  const title=document.createElement('div');title.className='plot-title';title.textContent='配对对照｜平均种群（真实EvoWorld计算）';
  const groups=[...new Set(data.results.map(r=>r.seed))];
  const max=Math.max(1,...data.results.map(r=>r.meanPopulation));
  for(const seed of groups){
   for(const item of data.results.filter(r=>r.seed===seed)){
    const line=document.createElement('div');line.style.cssText='display:grid;grid-template-columns:128px 1fr 60px;gap:10px;align-items:center;margin:12px 4px;font-size:11px;color:#496c5e';
    const label=document.createElement('span');label.textContent='种子'+seed+' · '+(item.condition==='合作开启'?'开启':'关闭');
    const bg=document.createElement('div');bg.style.cssText='height:12px;background:#e9f0eb;border-radius:8px;overflow:hidden';
    const bar=document.createElement('div');bar.style.cssText='height:100%;width:'+(100*item.meanPopulation/max).toFixed(2)+'%;border-radius:8px;background:'+(item.condition==='合作开启'?'#258264':'#e6a46b');
    bg.append(bar);const val=document.createElement('b');val.textContent=item.meanPopulation.toFixed(2);line.append(label,bg,val);t.append(line);
   }
  }
  t.prepend(title);plots.append(t);
  warn.textContent=data.warning;
 }else{
  (data.plots||[]).forEach((p,i)=>plots.append(drawPlot(p,i)));
  (data.metrics||[]).slice(0,6).forEach(x=>addMetric(metrics,x.label,x.value,x.unit));
  warn.textContent=(data.warnings||[]).join(' ') || '模型输出完成。';
 }
 $('raw-output').textContent=JSON.stringify({
  experiment:data.experiment,engine:data.engine,engineVersion:data.engineVersion,
  condition:data.condition,diagnostics:data.diagnostics,metrics:data.metrics,
  results:data.results,provenance:data.adapterSha256,runId:data.runId
 },null,2);
}
function drawPlot(plot,plotIndex){
 const wrap=document.createElement('div');wrap.className='plot-card';
 const h=document.createElement('div');h.className='plot-title';h.textContent=plot.title;wrap.append(h);
 const W=740,H=250,L=48,R=18,T=12,B=38;
 const series=plot.series.map((s,i)=>({label:s.label,color:['#258265','#dc9163','#6c76ba'][i%3],
  points:s.points.filter(p=>Array.isArray(p)&&p.length>=2&&Number.isFinite(p[0])&&Number.isFinite(p[1])&&(!plot.yScale||p[1]>0)).map(p=>[p[0],plot.yScale==='log'?Math.log10(p[1]):p[1]])}));
 const pts=series.flatMap(s=>s.points);
 if(!pts.length){const p=document.createElement('p');p.textContent='没有可显示的数据点';wrap.append(p);return wrap;}
 let xmin=Math.min(...pts.map(p=>p[0])),xmax=Math.max(...pts.map(p=>p[0]));
 let ymin=Math.min(...pts.map(p=>p[1])),ymax=Math.max(...pts.map(p=>p[1]));
 if(xmin===xmax)xmax=xmin+1;if(ymin===ymax){ymin-=.01;ymax+=.01;}
 const sx=x=>L+(x-xmin)/(xmax-xmin)*(W-L-R),sy=y=>T+(1-(y-ymin)/(ymax-ymin))*(H-T-B);
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 '+W+' '+H);svg.setAttribute('role','img');svg.classList.add('chart');
 svg.setAttribute('aria-label',plot.title+'的真实数据曲线');
 function el(tag,attrs){const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));svg.append(n);return n}
 for(let i=0;i<5;i++){
  const y=T+(H-T-B)*i/4;
  el('line',{x1:L,y1:y,x2:W-R,y2:y,stroke:'#e4ebe6','stroke-width':1});
  const val=ymax-(ymax-ymin)*i/4;
  const label=el('text',{x:L-7,y:y+4,'text-anchor':'end'});
  label.textContent=Number(val.toPrecision(3)).toString();
 }
 for(let i=0;i<5;i++){
  const x=L+(W-L-R)*i/4;
  const label=el('text',{x,y:H-15,'text-anchor':'middle'});
  label.textContent=Number((xmin+(xmax-xmin)*i/4).toPrecision(3)).toString();
 }
 for(const s of series){
  if(!s.points.length)continue;
  const coords=s.points.map(p=>[sx(p[0]),sy(p[1])]);
  const geometry=coords.map(p=>p.map(x=>x.toFixed(2)).join(',')).join(' ');
  el('polyline',{points:geometry,fill:'none',stroke:s.color,'stroke-width':'2','stroke-linecap':'round','stroke-linejoin':'round'});
 }
 wrap.append(svg);
 if(!plot.yScale){
  svg.style.cursor='crosshair';
  svg.addEventListener('click',ev=>{
   const rect=svg.getBoundingClientRect();
   const px=(ev.clientX-rect.left)*W/rect.width;
   const py=(ev.clientY-rect.top)*H/rect.height;
   let best=null;
   plot.series.forEach((s,si)=>s.points.forEach((point,pi)=>{
    if(!Number.isFinite(point[0])||!Number.isFinite(point[1]))return;
    const d=(sx(point[0])-px)**2+(sy(point[1])-py)**2;
    if(best===null||d<best.d)best={d,plotIndex,seriesIndex:si,pointIndex:pi,point,label:s.label};
   }));
   if(best){
    state.selection={plotIndex:best.plotIndex,seriesIndex:best.seriesIndex,pointIndex:best.pointIndex};
    $('point-selection').textContent='已选真实计算数据：'+best.label+'，横坐标='+Number(best.point[0].toPrecision(7))+'，纵坐标='+Number(best.point[1].toPrecision(7))+'。导师将以服务器保存的原始实验结果复核该点。';
   }
  });
 }
 const legend=document.createElement('div');legend.className='legend';
 series.forEach(s=>{const item=document.createElement('span'),line=document.createElement('i');line.style.background=s.color;
 item.append(line,document.createTextNode(s.label));legend.append(item)});
 wrap.append(legend);return wrap;
}
$('ask').addEventListener('click',async()=>{
 if(!state.runId||$('ask').disabled)return;
 const button=$('ask'),errorBox=$('mentor-action-error');
 button.disabled=true;errorBox.hidden=true;
 let started=false,finished=false;
 try{
  await refreshModelStatus();
  const authorized=state.modelActive&&$('shareApproved').checked;
  const runId=state.runId,note=$('reflection').value.trim(),selection=state.selection;
  button.textContent=authorized?'AI 导师正在分析…':'正在整理学习反馈…';
  document.dispatchEvent(new CustomEvent('academy:ai-start',{detail:{kind:'mentor',ai:authorized}}));
  started=true;
  const result=await request('/api/mentor',{runId,note,selection,shareApproved:authorized});
  document.dispatchEvent(new CustomEvent('academy:ai-end',{detail:{kind:'mentor',ai:result.mode==='llm',fallback:authorized&&result.mode!=='llm'}}));
  finished=true;
  if(state.runId!==runId)return;
  state.mentor=result;renderMentor(result);
  afterMentorResponse(result,note);
  const item=state.records.find(x=>x.id===runId);
  if(item){item.mentor=result;item.selection=selection;item.reflection=note;item.step='mentor';saveRecords()}
  await loadQuiz();activeStep(3);
 }catch(e){
  if(started&&!finished)document.dispatchEvent(new CustomEvent('academy:ai-end',{detail:{kind:'mentor',error:true}}));
  errorBox.textContent='导师反馈暂时无法完成：'+String(e.message||'网络或服务异常')+'。请确认连接状态后重试，已有实验数据不会被清空。';
  errorBox.hidden=false;
 }finally{
  $('shareApproved').checked=false;refreshAIChoice();
  button.disabled=false;button.textContent='请导师分析 →';
 }
});
function renderMentor(m){
 setLens('lens-next',(m.mode==='llm'?'AI 导师：':'导师提示：')+String(m.mode==='llm'?m.reply:(m.suggestion||m.question)||'请提出下一步验证问题').slice(0,120),'attention');
 const out=$('mentor-output');out.replaceChildren();out.classList.remove('hidden');
 $('agent-planning').classList.remove('hidden');
 $('plan-hint').textContent=state.modelActive?'勾选本次授权后，AI 将从经过校验的候选方案中选择；实验执行仍需你批准。':'尚未连接 AI。可先预览本地科学实验方案。';
 function row(title,body){const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=body;out.append(h,p)}
 const label=document.createElement('div');label.className='mode';
 const source=m.mode==='llm'?'真实 AI 回复 · '+(state.modelLabel||'当前模型'):m.fallbackReason?'AI 未完成 · 本地备用指导':'本地科学学习指导 · 未使用 AI';
 label.textContent=source+' · '+String(m.availability||'').slice(0,70);out.append(label);
 out.dataset.source=m.mode==='llm'?'ai':m.fallbackReason?'fallback':'local';
 row('真实观测',m.observed);if(m.reply)row('AI 导师引导',m.reply);
 if(m.qualityCheck)row('反馈核验范围',m.mode==='llm'?'已通过基础科学核对；仍请结合实验数据独立判断。':'建议未通过科学校验，本次使用备用引导。');
 if(m.fallbackReason){const reasons={TIMEOUT:'模型请求超时；可以稍后重试，本次实验与学习证据已保留。',EMPTY_RESPONSE:'模型没有返回可用正文，已保留规则反馈。',QUOTA_EXHAUSTED:'今日模型配额已用完，规则教学可继续。',NETWORK_OR_FORMAT:'网络或响应格式异常，规则教学可继续。',UPSTREAM_HTTP_429:'供应方限额，本次使用规则引导。'};if(reasons[m.fallbackReason])row('连接状态',reasons[m.fallbackReason]);}
 if(m.question)row('值得继续思考',m.question);
 if(m.suggestion)row('下一轮实验建议',m.suggestion);
 row('证据与限制',m.rationale);
 $('retry').classList.remove('hidden');
}
// V0.3: a constrained tool plan never executes until the student supplies a new
// prediction AND explicitly clicks approval. No API credential is required.
$('approval-prediction').addEventListener('input',()=>{
 const prediction=$('approval-prediction').value.trim();
 $('approve-plan').disabled=!state.pendingPlan||prediction.length<8||prediction===state.prediction;
});
$('request-plan').addEventListener('click',async()=>{
 if(!state.runId||!state.mentor||$('request-plan').disabled)return;
 const button=$('request-plan');
 button.disabled=true;
 await refreshModelStatus();
 const plannedAI=state.modelActive&&$('plan-model-consent').checked;
 button.textContent=plannedAI?'AI 正在规划…':'正在生成对照方案…';
 document.dispatchEvent(new CustomEvent('academy:ai-start',{detail:{kind:'plan',ai:plannedAI}}));
 $('plan-hint').textContent='正在核对工具范围和科学变量…';
 $('plan-preview').classList.add('hidden');
 document.dispatchEvent(new Event('academy:plan-reset'));
 state.pendingPlan=null;
 try{
  const authorizedModel=plannedAI;
  const p=await request('/api/agent/plan',{runId:state.runId,goal:$('planning-goal').value.trim(),
   mode:authorizedModel?'llm':'rules',shareApproved:authorizedModel});
  state.pendingPlan=p;
  document.dispatchEvent(new CustomEvent('academy:ai-end',{detail:{kind:'plan',ai:p.plannerMode==='llm-constrained',fallback:!!p.fallbackReason}}));
  document.dispatchEvent(new CustomEvent('academy:plan-ready',{detail:{
   sourceRunId:state.runId,experiment:state.experiment,plannerMode:p.plannerMode,
   fallbackReason:p.fallbackReason||null,studyQuestion:p.studyQuestion,
   changes:p.changes,limits:p.limits,budget:p.budget
  }}));
  $('plan-question').textContent=p.studyQuestion;
  const c=p.changes[0];
  const labels={logDelta:'初值扰动 log₁₀(δ)',r:'映射参数 r',seed:'配对随机种子'};
  $('plan-change').textContent='科学工具：'+p.toolId+' · 仅改变 '+(labels[c.field]||c.field)+
   '：'+c.from+' → '+c.to+' · 其余控制变量保持原样';
  $('plan-reason').textContent=p.why;
  $('plan-limits').textContent='模型与推断边界：'+p.limits+'；'+p.note;
  setLens('lens-next',(p.plannerMode==='llm-constrained'?'AI 推荐的下一轮实验：':'可验证的对照实验：')+
   c.field+' '+c.from+' → '+c.to+'。等待新预测和学生批准。','ready');
  $('approval-prediction').value='';
  $('approve-plan').disabled=true;
  $('plan-preview').classList.remove('hidden');
  $('plan-hint').textContent=(p.plannerMode==='llm-constrained'?'真实 AI 已选择科学实验方案；':p.fallbackReason?'AI 本次未成功，已提供本地方案；':'本地科学方案已验证；')+'尚未执行。请写新预测并明确批准。';
  $('plan-preview').dataset.source=p.plannerMode==='llm-constrained'?'ai':p.fallbackReason?'fallback':'local';
 }catch(e){
  document.dispatchEvent(new CustomEvent('academy:ai-end',{detail:{kind:'plan',error:true}}));
  $('plan-hint').textContent='无法生成方案：'+e.message;
 }
 finally{$('plan-model-consent').checked=false;refreshAIChoice();button.disabled=false;button.textContent='生成对照方案 →'}
});
$('discard-plan').addEventListener('click',()=>{
 state.pendingPlan=null;
 $('plan-preview').classList.add('hidden');
 $('approval-prediction').value='';
 $('approve-plan').disabled=true;
 $('plan-hint').textContent='已放弃当前方案，科学引擎没有运行。';
 document.dispatchEvent(new Event('academy:plan-reset'));
 setLens('lens-next','实验方案已放弃，原始科学结果没有改变。','attention');
});
function renderExperimentComparison(prior,next,plan){
 const root=$('experiment-comparison');
 root.replaceChildren();root.classList.remove('hidden');
 const head=document.createElement('strong');
 head.textContent='学生批准的受控复现实验 · 第'+plan.round+'轮';
 const change=document.createElement('div');
 const field=plan.changes[0];
 change.textContent='已实际执行 '+plan.toolId+'：'+field.field+
  ' 从 '+field.from+' 改为 '+field.to+'；其余控制变量维持不变。';
 const observation=document.createElement('div');
 if(next.experiment==='evo-pair'){
  function diff(result){
   const a=result.results.filter(v=>v.condition==='合作开启');
   const b=result.results.filter(v=>v.condition==='合作关闭');
   return a.reduce((t,v)=>t+v.meanPopulation,0)/a.length-
    b.reduce((t,v)=>t+v.meanPopulation,0)/b.length;
  }
  observation.textContent='模型内合作开启−关闭的平均种群差：上一轮 '+
   diff(prior).toFixed(3)+'，本轮 '+diff(next).toFixed(3)+
   '。少量模拟世界不足以支持普遍因果结论。';
 }else{
  const one=(next.metrics||[]).find(m=>Number.isFinite(Number(m.value))&&
   (prior.metrics||[]).some(v=>v.label===m.label&&Number.isFinite(Number(v.value))));
  const old=one?(prior.metrics||[]).find(v=>v.label===one.label):null;
  observation.textContent=one?
   '同一指标「'+one.label+'」：上一轮 '+old.value+'，本轮 '+one.value+
   '。不同轨道可能存在数值敏感性，请结合曲线与警告判断。':
   '两轮条件均已保留。请比较真实曲线及各项诊断，不要仅凭单一指标下结论。';
 }
 const provenance=document.createElement('div');
 provenance.textContent='实验由本机科学引擎实际运行；计划与预测已记录在学习导出中。';
 root.append(head,change,observation,provenance);
}
$('approve-plan').addEventListener('click',async()=>{
 const p=state.pendingPlan;
 const prediction=$('approval-prediction').value.trim();
 if(!p||prediction.length<8||prediction===state.prediction)return;
 const button=$('approve-plan');
 button.disabled=true;button.textContent='正在执行经批准的真实科学实验…';
 const prior=state.result;
 try{
  const result=await request('/api/agent/approve',{planId:p.planId,prediction});
  state.runId=result.runId;state.result=result;state.prediction=prediction;
  state.mentor=null;state.answer=null;state.selection=null;state.pendingPlan=null;
  if(result.experiment==='evo-pair'){
   $('seed').value=String(result.condition.baseSeed);
  }else{
   for(const [k,value] of Object.entries(result.condition)){
    const id=k==='logDelta'?'delta':k;
    if($(id)){$(id).value=String(value);$(id).dispatchEvent(new Event('input'))}
   }
  }
  $('prediction-input').value=prediction;
  $('prediction-input').disabled=true;
  ['r','x0','delta','steps','seed'].forEach(k=>$(k).disabled=true);
  $('run').disabled=true;
  $('hint').textContent='此实验由你审阅并批准了明确的单变量修改方案，预测已锁定。';
  $('mentor-output').classList.add('hidden');
  $('agent-planning').classList.add('hidden');
  $('plan-preview').classList.add('hidden');
  $('retry').classList.add('hidden');
  $('transfer').classList.add('hidden');
  $('reflection').value='';
  $('shareApproved').checked=false;
  $('plan-model-consent').checked=false;
  renderResult(result);
  renderExperimentComparison(prior,result,p);
  document.dispatchEvent(new CustomEvent('academy:plan-approved',{detail:{runId:result.runId}}));
  $('results').classList.remove('hidden');$('tutoring').classList.remove('hidden');
  markResult();activeStep(2);
  $('results').scrollIntoView({behavior:'smooth',block:'start'});
 }catch(e){
  $('plan-hint').textContent='本次执行没有成功：'+e.message;
  // Keep the plan ID only for review; the server may have consumed it.
 }finally{
  button.textContent='我批准，执行这次实验 →';
  if(state.pendingPlan)button.disabled=false;
 }
});
async function loadQuiz(){
 const r=await fetch('/api/transfer?runId='+encodeURIComponent(state.runId)),data=await r.json();
 $('quiz-prompt').textContent=data.prompt;
 const group=$('quiz-options');group.replaceChildren();
 data.options.forEach((option,i)=>{
  const label=document.createElement('label');label.className='choice';
  const input=document.createElement('input');input.type='radio';input.name='transfer-answer';input.value=String(i);
  // Intentionally no checked/default answer: user must choose.
  input.addEventListener('change',()=>{$('grade').disabled=false});
  label.append(input,document.createTextNode(option));group.append(label);
 });
 $('grade').disabled=true;$('quiz-feedback').classList.add('hidden');$('transfer').classList.remove('hidden');
}
$('grade').addEventListener('click',async()=>{
 const selected=document.querySelector('input[name="transfer-answer"]:checked');
 if(!selected||!state.runId)return;
 $('grade').disabled=true;
 try{
  const res=await request('/api/evaluate',{runId:state.runId,answer:Number(selected.value)});
  const out=$('quiz-feedback');out.className='feedback'+(res.correct?'':' wrong');
  out.textContent=(res.correct?'回答正确。':'还需要修正理解。')+res.explanation;
  state.answer={choice:Number(selected.value),correct:res.correct,feedback:res.explanation};
  const item=state.records.find(x=>x.id===state.runId);
  if(item){item.transfer=state.answer;item.step='complete';saveRecords()}
  activeStep(4);$('transfer').scrollIntoView({behavior:'smooth',block:'center'});
 }catch(e){alert(e.message);$('grade').disabled=false}
});
$('retry').addEventListener('click',()=>{
 const exp=state.experiment;
 $('prediction-input').disabled=false;
 ['r','x0','delta','steps','seed'].forEach(k=>$(k).disabled=false);
 if(exp==='sensitivity'){$('delta').value=String(Math.min(-3,Number($('delta').value)+3));$('delta').dispatchEvent(new Event('input'))}
 selectExperiment(exp);
 window.scrollTo({top:0,behavior:'smooth'});
});
$('download-learning').addEventListener('click',()=>{try{exportLearningEvidence()}catch(e){alert(e.message)}});
$('download-record').addEventListener('click',()=>{
 const payload={product:'AI学院',version:'0.1.0',notice:'本地学生预测与真实实验记录；模型内观测不代表外部现实证明',records:state.records};
 const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
 const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download='AI学院-科学探究记录.json';anchor.click();URL.revokeObjectURL(url);
});
$('clear-record').addEventListener('click',()=>{
 if(!confirm('将清除当前浏览器的V0.3旧记录及V2学习证据（包括错题、复习和试测记录）。请先导出备份，确定吗？'))return;
 state.records=[];localStorage.removeItem('ai-academy-learning-v01');resetLearningEvidence();
 alert('本机探究与学习记录已清空；不影响电脑其他项目。');
});
async function refreshModelStatus(){
 try{
  const response=await fetch('/api/status',{cache:'no-store'}),s=await response.json();
  if(!response.ok||s.ok!==true)throw new Error('状态接口暂不可用');
  state.modelActive=s.mentorMode==='llm-configured';
  state.modelLabel=state.modelActive?String(s.provider||'AI')+' · '+String(s.model||'模型'):'';
  document.dispatchEvent(new CustomEvent('academy:model-status',{detail:s}));
  $('engine-version').textContent='PFL '+s.pflVersion+' · EvoWorld '+s.evoVersion;
  const codingPlanDemo=s.providerSource==='isolated-Pi-RPC';
  if(codingPlanDemo){
   const parent=document.querySelector('.content');
   let notice=document.getElementById('codingplan-demo-notice');
   if(!notice&&parent){
    notice=document.createElement('div');notice.id='codingplan-demo-notice';
    notice.className='codingplan-demo-notice';parent.prepend(notice);
   }
   if(notice)notice.textContent='研发现场演示｜真实 Coding Plan / DeepSeek V4.1 Flash · 仅限合成学生案例。两处模型调用均需要单独勾选授权；模型不会自动执行实验。本页面不是学校正式部署。';
   const consent=document.querySelector('#privacy-consent span');
   if(consent)consent.textContent='我同意将本次合成预测、反思及真实实验摘要发送到个人 Coding Plan，供本机研发演示；不含凭据和历史记录。';
   const planConsent=document.querySelector('#plan-model-consent-wrap span');
   if(planConsent)planConsent.textContent='我同意由 Coding Plan 真实模型从两个科学校验通过的候选中选择下一步；不发送历史记录，不自动执行。';
  }
  $('model-state').textContent=state.modelActive?(codingPlanDemo?'研发演示 AI：':(s.providerSource==='judge-session'||s.providerSource==='browser-BYOK')?'我的 AI：':'学校 AI：')+s.provider+(s.providerVerified?' ✓':'（待验证）'):'AI 尚未连接';
  $('institution-provider').textContent=state.modelActive?'当前模型：'+s.provider+' · '+s.model+'（Key 仅保存在本标签页内存中）':'选择 DeepSeek 官方 API，连接你的 AI 导师';
  $('mentor-connection-note').textContent=state.modelActive?'已配置 '+s.provider+'，勾选授权后才会使用 AI。':'尚未连接 AI；点击首页“配置我的 AI”即可启用';
  $('privacy-consent').hidden=!state.modelActive;
  $('plan-model-consent-wrap').hidden=!state.modelActive;
  if(!state.modelActive){$('shareApproved').checked=false;$('plan-model-consent').checked=false;}
  refreshAIChoice();
 }catch{
  state.modelActive=false;state.modelLabel='';$('model-state').textContent='模型状态暂不可用';
  $('institution-provider').textContent='暂时无法读取模型状态，请确认本机服务是否在线';
  $('mentor-connection-note').textContent='当前无法确认模型连接，暂不发送学习数据';
  $('privacy-consent').hidden=true;$('plan-model-consent-wrap').hidden=true;
  $('shareApproved').checked=false;$('plan-model-consent').checked=false;
  document.dispatchEvent(new CustomEvent('academy:model-status',{detail:{mentorMode:'unavailable'}}));
  refreshAIChoice();
 }
}
initializeLearningChecks();
refreshModelStatus();
window.addEventListener('focus',refreshModelStatus);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshModelStatus()});

// ZHIXU_DOCTOR_WIDGET_HOT_RC4
(()=>{
// 知序博士 — presentation-only assistant UI. Never reads or stores API credentials.
const root=document.createElement('aside');
root.className='zhixu-doctor';
root.setAttribute('aria-label','知序博士 AI 导师状态');
root.dataset.collapsed='false';
root.innerHTML=`
 <button type="button" id="doctor-toggle" class="doctor-toggle" aria-label="收起导师侧栏" aria-expanded="true" title="收起导师侧栏">−</button>
 <div class="doctor-profile">
  <div class="doctor-portrait" aria-hidden="true"><img id="doctor-art" class="doctor-art" alt="" decoding="async"/><div class="doctor-orbit"></div><div class="doctor-hair"></div><div class="doctor-head"><div class="doctor-glasses"></div><div class="doctor-smile"></div></div><div class="doctor-coat"><span class="doctor-tie"></span></div></div>
  <div class="doctor-heading"><small>ZHIXU INTELLIGENCE</small><strong>知序博士</strong><span>你的科学探究导师</span></div>
 </div>
 <div class="doctor-state"><span class="doctor-light" id="doctor-light"></span><strong id="doctor-status">正在确认模型状态</strong></div>
 <p id="doctor-message">我会根据你的预测与真实实验结果，陪你一步步验证想法。</p>
 <div class="doctor-timer" id="doctor-timer" hidden><span class="doctor-loader" aria-hidden="true"></span><span id="doctor-timer-text">正在思考 · 0.0 秒</span></div>
 <div class="doctor-model"><small>当前模型</small><strong id="doctor-model-name">正在检测…</strong></div>
 <a id="doctor-connect" href="/connect">管理 AI 连接 ↗</a>`;
document.body.append(root);
let start=0,timer=null;
const artMap={"analyzing":"data:image/webp;base64,","encouraging":"data:image/webp;base64,","explaining":"data:image/webp;base64,","fallback":"data:image/webp;base64,","idle":"data:image/webp;base64,","planning":"data:image/webp;base64,","success":"data:image/webp;base64,","teaching":"data:image/webp;base64,","thinking":"data:image/webp;base64,","warning":"data:image/webp;base64,","welcome":"data:image/webp;base64,"};
const art=document.getElementById('doctor-art');
function setArt(state){const known=Object.hasOwn(artMap,state);const key=known?state:'idle';root.dataset.requestedArt=state;root.dataset.knownArt=String(known);root.dataset.expression=key;art.src=artMap[key]}
art.addEventListener('load',()=>root.classList.add('doctor-has-art'));
art.addEventListener('error',()=>root.classList.remove('doctor-has-art'));
setArt('idle');
const status=document.getElementById('doctor-status'),msg=document.getElementById('doctor-message'),light=document.getElementById('doctor-light'),model=document.getElementById('doctor-model-name'),time=document.getElementById('doctor-timer'),timeText=document.getElementById('doctor-timer-text');
const toggle=document.getElementById('doctor-toggle');
toggle.addEventListener('click',()=>{
 const collapsed=root.dataset.collapsed!=='true';
 root.dataset.collapsed=String(collapsed);
 document.body.classList.toggle('doctor-collapsed',collapsed);
 toggle.textContent=collapsed?'+':'−';
 toggle.setAttribute('aria-expanded',String(!collapsed));
 toggle.setAttribute('aria-label',collapsed?'展开导师侧栏':'收起导师侧栏');
 toggle.title=collapsed?'展开导师侧栏':'收起导师侧栏';
});
// Compact by default on phone-sized screens so controls and evidence remain visible.
if(window.matchMedia('(max-width:560px)').matches)toggle.click();
function setWorking(kind,ai=false){
 setArt(ai?(kind==='plan'?'planning':'thinking'):(kind==='plan'?'analyzing':'explaining'));
 clearInterval(timer);start=performance.now();time.hidden=false;root.dataset.state='working';
 status.textContent=ai?'AI 正在思考':'正在核对科学证据';
 msg.textContent=kind==='plan'?(ai?'AI 正在选择经过校验的下一轮方案…':'正在核对变量限制与实验依据…'):(ai?'AI 正在阅读你的预测与科学观测…':'正在整理本次学习证据…');
 const tick=()=>{timeText.textContent=(ai?'AI 思考中':'科学任务处理中')+' · '+((performance.now()-start)/1000).toFixed(1)+' 秒'};
 tick();timer=setInterval(tick,100);
}
function finish({ai=false,fallback=false,error=false,kind='mentor'}={}){
 if(!start)return;
 clearInterval(timer);timer=null;
 const seconds=((performance.now()-start)/1000).toFixed(1);
 start=0;time.hidden=true;root.dataset.state=error?'error':fallback?'fallback':'ready';
 setArt(error?'warning':fallback?'fallback':ai?(kind==='plan'?'success':'teaching'):(kind==='plan'?'encouraging':'explaining'));
 status.textContent=error?'请求未完成':fallback?'已启用备用引导':ai?'AI 已完成':kind==='plan'?'科学方案已完成':'学习反馈已完成';
 const detail=error?'本次请求未成功，请检查网络与模型状态后重试。':fallback?'AI 本次没有得到可用回复，已保留科学实验与备用引导。':kind==='plan'?'实验方案已生成，执行前仍需你的预测和批准。':'导师反馈已生成，请继续核对真实实验结果。';
 msg.textContent=detail+' · 用时 '+seconds+' 秒';
}
document.addEventListener('academy:model-status',({detail:s})=>{
 const active=s?.mentorMode==='llm-configured',unknown=s?.mentorMode==='unavailable';
 root.dataset.connected=active?'true':'false';
 light.classList.toggle('live',active&&!!s.providerVerified);
 if(timer===null)setArt(unknown?'warning':active?'idle':'welcome');
 model.textContent=unknown?'模型状态待确认':active?(s.provider||'AI')+' · '+(s.model||'已配置模型'):'尚未配置';
 if(!timer){
  status.textContent=unknown?'连接状态暂不可用':active?(s.providerVerified?'AI 已连接 · 已验证':'AI 已配置 · 待验证'):'尚未连接 AI';
  msg.textContent=unknown?'暂时无法确认模型服务，当前不会上传学习数据。请检查连接后重试。':active?'完成科学实验并授权后，我会根据真实证据提供引导。':'科学实验可以直接开始；连接 AI 后，我会提供个性化分析。';
 }
 const c=document.querySelector('.institution-banner a[href="/connect"]');
 if(c)c.textContent=unknown?'检查模型设置 ↗':active?'管理当前 AI ↗':'配置我的 AI →';
 const bannerTitle=document.querySelector('.institution-banner strong');
 if(bannerTitle)bannerTitle.textContent=unknown?'模型状态待确认':active?(s.providerVerified?'AI 导师在线 · ':'AI 导师已配置 · ')+(s.provider||'模型'):'连接你的 AI 导师';
 const connect=document.getElementById('doctor-connect');
 if(connect)connect.textContent=unknown?'检查连接设置 ↗':active?'管理模型设置 ↗':'配置我的 AI ↗';
 const link=document.querySelector('.rail-bottom a[href="/connect"]');
 if(link)link.textContent=unknown?'检查 AI 模型状态 ↗':active?'管理已连接的 AI ↗':'连接我的 AI 模型 ↗';
});
document.addEventListener('academy:ai-start',e=>setWorking(e.detail?.kind,e.detail?.ai));
document.addEventListener('academy:ai-end',e=>finish(e.detail||{}));
window.addEventListener('pageshow',()=>fetch('/api/status',{cache:'no-store'}).then(r=>r.json()).then(s=>document.dispatchEvent(new CustomEvent('academy:model-status',{detail:s}))).catch(()=>{}));
})();
